<?php require '../config/database.php'; require_once '../config/auth.php'; require_role('user'); if($_SERVER['REQUEST_METHOD']=='POST'){ $uid=$_SESSION['user_id']; $c=mysqli_real_escape_string($conn,$_POST['content']); mysqli_query($conn,"INSERT INTO community_posts(user_id,content) VALUES($uid,'$c')"); } if(isset($_GET['like'])){ $id=(int)$_GET['like']; mysqli_query($conn,"UPDATE community_posts SET likes=likes+1 WHERE id=$id"); header('Location: community.php'); exit; } $posts=mysqli_query($conn,"SELECT p.*,u.full_name FROM community_posts p JOIN users u ON p.user_id=u.id ORDER BY p.created_at DESC"); ?>
<!DOCTYPE html><html><head><title>Community</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="layout"><?php include '_nav.php'; ?><main class="main"><h1>Wellness Community Feed</h1><form class="form" method="post"><label>Share progress, recipe, or motivation</label><textarea name="content" required></textarea><button>Post</button></form><br><?php while($p=mysqli_fetch_assoc($posts)):?><div class="card" style="margin-bottom:14px"><h3><?=e($p['full_name'])?></h3><p><?=e($p['content'])?></p><small><?=$p['created_at']?></small><p><a class="btn light" href="?like=<?=$p['id']?>">❤️ Like (<?=$p['likes']?>)</a></p></div><?php endwhile;?></main></div></body></html>
